  (4, '2-Bedroom Apartment in Mowe', 'Residential', 'For Sale', 25000000, 'Mowe, Ogun State', 'Da''sayonce Mini-Estate, Mowe, Ogun State', 2, 2, '120 sqm', 'An affordable yet quality apartment in our gated estate. Perfect for young professionals and small families. Part of our Da''sayonce Mini-Estate development with excellent amenities.', array['Gated Estate', '24/7 Security', 'Water Supply', 'Power Backup', 'Playground', 'Good Road Network', 'Parking Space', 'Modern Finishing', 'Recreational Areas', 'Close to Major Roads']::text[], 'https://images.pexels.com/photos/280222/pexels-photo-280222.jpeg', array['https://images.pexels.com/photos/280222/pexels-photo-280222.jpeg', 'https://images.pexels.com/photos/271816/pexels-photo-271816.jpeg', 'https://images.pexels.com/photos/271624/pexels-photo-271624.jpeg']::text[], 2023, 2, false, 'Mrs. Folusho Mogaji', '+234 706 425 8898', 'folusho@dasayoncerealestate.com', false, true, '2024-01-05'),
