  (6, '5-Bedroom Detached House in Magodo', 'Residential', 'For Sale', 180000000, 'Magodo, Lagos', 'Magodo Phase 2, Lagos', 5, 6, '500 sqm', 'A magnificent detached house in the prestigious Magodo area. Features include a large compound, modern amenities, and excellent security. Perfect for large families.', array['Large Compound', 'BQ Apartment', 'Swimming Pool', 'Generator House', 'Security House', 'Ample Parking', 'Modern Kitchen', 'Master Suite', 'Study Room', 'Family Lounge']::text[], 'https://images.pexels.com/photos/1396132/pexels-photo-1396132.jpeg', array['https://images.pexels.com/photos/1396132/pexels-photo-1396132.jpeg', 'https://images.pexels.com/photos/1396119/pexels-photo-1396119.jpeg', 'https://images.pexels.com/photos/1396118/pexels-photo-1396118.jpeg']::text[], 2019, 6, false, 'Realtor Ebenezer Ilupeju', '+234 8102 067 476', 'ebenezer@dasayoncerealestate.com', false, true, '2024-01-01'),
  (7, 'Luxury Penthouse in Ikoyi', 'Residential', 'For Rent', 15000000, 'Ikoyi, Lagos', 'Banana Island, Ikoyi, Lagos', 3, 4, '300 sqm', 'An exclusive penthouse offering breathtaking views of Lagos lagoon. Features top-of-the-line finishes, private terrace, and access to premium amenities.', array['Lagoon View', 'Private Terrace', 'Jacuzzi', 'Walk-in Closets', 'Premium Finishes', 'Concierge Service', 'Private Elevator', 'Wine Cellar', 'Smart Home System', 'Valet Parking']::text[], 'https://images.pexels.com/photos/1571470/pexels-photo-1571470.jpeg', array['https://images.pexels.com/photos/1571470/pexels-photo-1571470.jpeg', 'https://images.pexels.com/photos/1571471/pexels-photo-1571471.jpeg', 'https://images.pexels.com/photos/1457845/pexels-photo-1457845.jpeg']::text[], 2023, 3, true, 'Mrs. Folusho Mogaji', '+234 706 425 8898', 'folusho@dasayoncerealestate.com', false, true, '2023-12-28'),
  (8, 'Office Space in Mainland Business District', 'Commercial', 'For Rent', 5000000, 'Yaba, Lagos', 'Herbert Macaulay Way, Yaba, Lagos', null, null, '200 sqm', 'Modern office space in the heart of Lagos mainland business district. Perfect for startups and established businesses. Features modern amenities and excellent connectivity.', array['Open Plan Layout', 'Meeting Rooms', 'High-Speed Internet', 'Air Conditioning', 'Power Backup', 'Security System', 'Parking Spaces', 'Reception Area', 'Kitchenette', 'Flexible Terms']::text[], 'https://images.pexels.com/photos/2747449/pexels-photo-2747449.jpeg', array['https://images.pexels.com/photos/2747449/pexels-photo-2747449.jpeg', 'https://images.pexels.com/photos/1170412/pexels-photo-1170412.jpeg', 'https://images.pexels.com/photos/1181406/pexels-photo-1181406.jpeg']::text[], 2021, 10, true, 'Realtor Adekunle Alliu', '+234 706 425 8898', 'adekunle@dasayoncerealestate.com', false, true, '2023-12-25')
